
`timescale 1ns/1ps
module tb_width_6to64;
    reg [5:0] in_val;
    wire [63:0] Y_sized;

    // Sized expression (as generated by compiler)
    assign Y_sized  = 64'b1 << in_val;

    integer err_sized = 0;
    integer tested_count = 0;

    initial begin
        
        in_val = 6'd0;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[0] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 0, Y_sized[0]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (0 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 0);
        end
        tested_count = tested_count + 1;

        in_val = 6'd1;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[1] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 1, Y_sized[1]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (1 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 1);
        end
        tested_count = tested_count + 1;

        in_val = 6'd31;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[31] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 31, Y_sized[31]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (31 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 31);
        end
        tested_count = tested_count + 1;

        in_val = 6'd32;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[32] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 32, Y_sized[32]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (32 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 32);
        end
        tested_count = tested_count + 1;

        in_val = 6'd62;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[62] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 62, Y_sized[62]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (62 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 62);
        end
        tested_count = tested_count + 1;

        in_val = 6'd63;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[63] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 63, Y_sized[63]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (63 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 63);
        end
        tested_count = tested_count + 1;

        $display("SUMMARY_6to64: tested=%0d err_sized=%0d", tested_count, err_sized);
        $finish;
    end
endmodule
